using FMODUnity;
using NaughtyAttributes;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "CharacterSFXData", menuName = "Data/SFX/CharacterSFXData")]
public class CharacterSFXData : SFXData
{
	[SerializeField]
	private EventReference usingDice;

	[SerializeField]
	private EventReference losingHeart;

	[SerializeField]
	private EventReference losingGame;

	[SerializeField]
	private EventReference talking;

	public EventReference UsingDice => usingDice;

	public EventReference Talking => talking;

	[Button(null)]
	public void PlayerLosingHeartSFX()
	{
		ReferenceSingleton<SFXHandler>.Instance.PlaySFX(losingHeart);
	}

	[Button(null)]
	public void PlayerLosingGameSFX()
	{
		ReferenceSingleton<SFXHandler>.Instance.PlaySFX(losingGame);
	}

	[Button(null)]
	public void PlayerTalkingSFX()
	{
		ReferenceSingleton<SFXHandler>.Instance.PlaySFX(talking);
	}
}
